<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Usuario; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash;
class UsuarioController extends Controller { public function index(Request $r){$q=$r->query('busca_nome');$usuarios=Usuario::when($q,fn($x)=>$x->where('nome','like','%'.$q.'%'))->orderBy('nome')->paginate(20)->withQueryString();return view('admin.usuarios.index',compact('usuarios','q'));} public function create(){return view('admin.usuarios.form',['usuario'=>new Usuario]);} public function store(Request $r){$d=$this->validar($r);$d['senha']=Hash::make($d['senha']);$d['permissao']=implode(',',$r->input('permissoes',[]));Usuario::create($d);return redirect()->route('admin.usuarios.index')->with('sucesso','Usuário cadastrado.');} public function edit(Usuario $usuario){return view('admin.usuarios.form',compact('usuario'));} public function update(Request $r,Usuario $usuario){$d=$this->validar($r,$usuario->id,true);if(empty($d['senha']))unset($d['senha']);else $d['senha']=Hash::make($d['senha']);$d['permissao']=implode(',',$r->input('permissoes',[]));$usuario->update($d);return redirect()->route('admin.usuarios.index')->with('sucesso','Usuário atualizado.');} public function destroy(Usuario $usuario){abort_if(auth()->id()===$usuario->id,422,'Você não pode excluir seu próprio usuário.');$usuario->delete();return back()->with('sucesso','Usuário excluído.');} private function validar(Request $r,$id=null,$update=false){return $r->validate(['nome'=>'required|string|max:100','email'=>'required|email|max:100|unique:usuarios,email'.($id?','.$id:''),'setor'=>'required|string|max:50','senha'=>($update?'nullable':'required').'|string|min:4','permissoes'=>'nullable|array']);}}
